n = 24

# Build adjacency
adj = [[] for _ in range(n)]
for u,v in edges:
    adj[u].append(v)
    adj[v].append(u)

# Check girth using BFS
from collections import deque

def shortest_cycle(adj, start):
    # BFS to find shortest cycle through start
    dist = [-1]*n
    parent = [-1]*n
    q = deque([start])
    dist[start] = 0
    min_cycle = float('inf')
    while q:
        u = q.popleft()
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                parent[v] = u
                q.append(v)
            elif v != parent[u]:
                # Found a cycle
                cycle_len = dist[u] + dist[v] + 1
                if cycle_len < min_cycle:
                    min_cycle = cycle_len
    return min_cycle

girth = float('inf')
for i in range(n):
    c = shortest_cycle(adj, i)
    if c < girth:
        girth = c
print(f"Girth: {girth}")

# Check 3-colorability using backtracking
def is_3_colorable(adj):
    colors = [-1]*n
    def backtrack(v):
        if v == n:
            return True
        used = set()
        for u in adj[v]:
            if colors[u] != -1:
                used.add(colors[u])
        for c in range(3):
            if c not in used:
                colors[v] = c
                if backtrack(v+1):
                    return True
                colors[v] = -1
        return False
    return backtrack(0), colors

ok, colors = is_3_colorable(adj)
print(f"3-colorable: {ok}")
if ok:
    print(f"Coloring: {colors}")

